#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int INF = 1e18;

struct Edge {
    int to, rev;
    ll cap;
    Edge(int to_, int rev_, ll cap_) : to(to_), rev(rev_), cap(cap_) {}
};

vector<vector<Edge>> graph;
int n, m, k;
int s1, s2, f;

ll max_flow;
vector<vector<ll>> min_cut;

void add_edge(int from, int to, ll cap) {
    graph[from].push_back(Edge(to, (int)graph[to].size(), cap));
    graph[to].push_back(Edge(from, (int)graph[from].size()-1, 0));
}

ll max_bipartition(int a, int b) {
    ll res = 0;
    queue<pair<int, int>> q;
    q.push({a, -1});
    q.push({b, -1});
    unordered_set<int> visited1, visited2;
    while (!q.empty()) {
        auto [u, v] = q.front(); q.pop();
        if (u == a && v == -1) return res;
        if (u == b && v == -1) return res;
        if (visited1.find(u) != visited1.end()) continue;
        if (visited2.find(u) != visited2.end()) continue;
        visited1.insert(u);
        visited2.insert(v);
        for (const Edge& e : graph[u]) {
            if (e.cap > 0 && e.to != v) {
                q.push({e.to, v});
                e.cap--;
            } else if (e.cap < LLONG_MAX && e.to == v) {
                q.push({u, v});
                e.cap++;
            }
        }
    }
    return -1; // Shouldn't reach here
}

int main() {
    cin >> n >> m >> k;
    cin >> s1 >> s2 >> f;
    graph.resize(n+1);
    min_cut.resize(n+1, vector<ll>(n+1));

    for (int i = 0; i < m; ++i) {
        int a, b, c;
        cin >> a >> b >> c;
        add_edge(a, b, c);
    }

    for (int i = 0; i < k; ++i) {
        int a, b, l, r;
        cin >> a >> b >> l >> r;
        add_edge(a, b, LLONG_MAX);
        min_cut[a][b] = l;
        min_cut[b][a] = r;
    }

    while (true) {
        ll total = 0;
        vector<ll> levels;
        queue<int> q;
        q.push(s1);
        levels.push_back(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const Edge& e : graph[u]) {
                if (e.cap > 0 && e.to != f) {
                    total += e.cap;
                    q.push(e.to);
                    levels.push_back(levels[u]+1);
                }
            }
        }
        if (total == 0) break;

        ll b1 = max_bipartition(s1, f);
        ll b2 = max_bipartition(s2, f);

        if (b1 == -1 || b2 == -1) {
            cout << "LOSE" << endl;
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    cout << min_cut[i][j] << " ";
                }
                cout << endl;
            }
            return 0;
        }

        ll min_cut_b1 = min_cut[s1][f];
        ll min_cut_b2 = min_cut[s2][f];

        ll min_cut_b1_val = min_cut_b1;
        ll min_cut_b2_val = min_cut_b2;

        if (b1 != -1 && b2 != -1) {
            min_cut_b1_val = min(b1, min_cut_b1);
            min_cut_b2_val = min(b2, min_cut_b2);
        }

        ll delta = total - min_cut_b1_val - min_cut_b2_val;
        if (delta < 0) {
            cout << "LOSE" << endl;
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    cout << min_cut[i][j] << " ";
                }
                cout << endl;
            }
            return 0;
        }

        if (delta > 0) {
            cout << "WIN";
            vector<ll> res;
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    res.push_back(min_cut[i][j]);
                }
            }
            cout << " " << join(res, " ") << endl;
        } else {
            cout << "DRAW" << endl;
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    cout << min_cut[i][j] << " ";
                }
                cout << endl;
            }
        }
    }

    return 0;
}
